-- Three fictional RON accounts. Safe to rerun: existing accounts are preserved.
BEGIN;
INSERT OR IGNORE INTO accounts (id, currency, tier, cash_bani, state_json) VALUES ('demo-1', 'RON', 1, 75000, '{"accountId": "demo-1", "tierLevel": 1, "profile": {"name": "Ana Popescu", "email": "demo1@example.com", "accountNumber": "DEMO-RON-0001", "memberSince": "2026-10-28"}, "cash": 750, "holdings": {}, "transactions": [{"id": "opening-1", "date": "2026-10-28T08:00:00Z", "description": "Opening demo deposit", "amount": 750, "direction": "in", "status": "completed"}], "redeemed": {}, "completedLessons": []}');
INSERT OR IGNORE INTO accounts (id, currency, tier, cash_bani, state_json) VALUES ('demo-2', 'RON', 2, 350000, '{"accountId": "demo-2", "tierLevel": 2, "profile": {"name": "Andrei Ionescu", "email": "demo2@example.com", "accountNumber": "DEMO-RON-0002", "memberSince": "2026-10-28"}, "cash": 3500, "holdings": {}, "transactions": [{"id": "opening-2", "date": "2026-10-28T08:00:00Z", "description": "Opening demo deposit", "amount": 3500, "direction": "in", "status": "completed"}], "redeemed": {}, "completedLessons": ["l-budget", "l-emergency"]}');
INSERT OR IGNORE INTO accounts (id, currency, tier, cash_bani, state_json) VALUES ('demo-3', 'RON', 3, 850000, '{"accountId": "demo-3", "tierLevel": 3, "profile": {"name": "Maria Dumitrescu", "email": "demo3@example.com", "accountNumber": "DEMO-RON-0003", "memberSince": "2026-10-28"}, "cash": 8500, "holdings": {}, "transactions": [{"id": "opening-3", "date": "2026-10-28T08:00:00Z", "description": "Opening demo deposit", "amount": 8500, "direction": "in", "status": "completed"}], "redeemed": {}, "completedLessons": ["l-budget", "l-emergency", "l-compound", "l-diversify"]}');
UPDATE accounts SET state_json = json_set(state_json,
  '$.profile.monthlyIncome', CASE id WHEN 'demo-1' THEN 5000 WHEN 'demo-2' THEN 7000 ELSE 10000 END,
  '$.savingsStartedAt', strftime('%Y-%m-%dT%H:%M:%fZ', 'now'))
WHERE id IN ('demo-1', 'demo-2', 'demo-3') AND json_extract(state_json, '$.profile.monthlyIncome') IS NULL;
COMMIT;
